set.seed(25)
N_FOLDS &lt;- 10
games_folds &lt;- batted_balls |&gt; 
  distinct(game_date, home_team, away_team) |&gt;
  mutate(fold = sample(rep(1:N_FOLDS, length.out = n())))

batted_balls &lt;- batted_balls |&gt; 
